func (this *Bitvavo) ParseMarkets(markets any) []any {
	var result []any = []any{}
	for i := 0; i < GetArrayLength(markets); i++ {
		var market map[string]any = SafeMapTyped(markets, i)
		var id *string = this.SafeString(market, "market")
		var baseId *string = this.SafeString(market, "base")
		var quoteId *string = this.SafeString(market, "quote")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var status *string = this.SafeString(market, "status")
		result = append(result, this.SafeMarketStructure(map[string]any{
			"id":             id,
			"symbol":         *base + "/" + *quote,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         false,
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         (status != nil && *status == "trading"),
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"taker":          this.SafeNumber(this.Fees["trading"], "taker"),
			"maker":          this.SafeNumber(this.Fees["trading"], "maker"),
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quantityDecimals"))),
				"price":  this.SafeNumber(market, "tickSize"),
				"cost":   this.ParseNumber(this.ParsePrecision(this.SafeString(market, "notionalDecimals"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "minOrderInBaseAsset"),
					"max": this.SafeNumber(market, "maxOrderInBaseAsset"),
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": this.SafeNumber(market, "minOrderInQuoteAsset"),
					"max": this.SafeNumber(market, "maxOrderInQuoteAsset"),
				},
			},
			"created": nil,
			"info":    market,
		}))
	}
	return result
}

