func (this *Bitvavo) ParseCurrency(rawCurrency any) map[string]any {
	//
	//     [
	//         {
	//             "symbol": "USDT",
	//             "displayTicker": "USDT",
	//             "name": "Tether",
	//             "slug": "tether",
	//             "popularity": -1,
	//             "decimals": 6,
	//             "depositFee": "0",
	//             "depositConfirmations": 64,
	//             "depositStatus": "OK",
	//             "withdrawalFee": "3.2",
	//             "withdrawalMinAmount": "3.2",
	//             "withdrawalStatus": "OK",
	//             "networks": [
	//               "ETH"
	//             ],
	//             "light": {
	//               "color": "#009393",
	//               "icon": { "hash": "4ad7c699", "svg": "https://...", "webp16": "https://...", "webp32": "https://...", "webp64": "https://...", "webp128": "https://...", "webp256": "https://...", "png16": "https://...", "png32": "https://...", "png64": "https://...", "png128": "https://...", "png256": "https://..."
	//               }
	//             },
	//             "dark": {
	//               "color": "#009393",
	//               "icon": { "hash": "4ad7c699", "svg": "https://...", "webp16": "https://...", "webp32": "https://...", "webp64": "https://...", "webp128": "https://...", "webp256": "https://...", "png16": "https://...", "png32": "https://...", "png64": "https://...", "png128": "https://...", "png256": "https://..."
	//               }
	//             },
	//             "visibility": "PUBLIC",
	//             "message": ""
	//         },
	//     ]
	//
	var fiatCurrencies any = this.HandleOption("fetchCurrencies", "fiatCurrencies", []any{})
	var id *string = this.SafeString(rawCurrency, "symbol")
	var code *string = this.SafeCurrencyCode(id)
	var isFiat bool = this.InArray(code, fiatCurrencies)
	var networks map[string]any = map[string]any{}
	var networksArray []any = SafeListTyped(rawCurrency, "networks")
	var deposit bool = (this.SafeString(rawCurrency, "depositStatus") != nil && *this.SafeString(rawCurrency, "depositStatus") == "OK")
	var withdrawal bool = (this.SafeString(rawCurrency, "withdrawalStatus") != nil && *this.SafeString(rawCurrency, "withdrawalStatus") == "OK")
	var active bool = deposit && withdrawal
	var withdrawFee *float64 = this.SafeNumber(rawCurrency, "withdrawalFee")
	var precision *string = this.SafeString(rawCurrency, "decimals", "8")
	var minWithdraw *float64 = this.SafeNumber(rawCurrency, "withdrawalMinAmount")
	// btw, absolutely all of them have 1 network atm
	for j := 0; j < len(networksArray); j++ {
		var networkId any = networksArray[j]
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		if networkCode != nil {
			networks[*networkCode] = map[string]any{
				"info":      rawCurrency,
				"id":        networkId,
				"network":   networkCode,
				"active":    active,
				"deposit":   deposit,
				"withdraw":  withdrawal,
				"fee":       withdrawFee,
				"precision": this.ParseNumber(this.ParsePrecision(precision)),
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": minWithdraw,
						"max": nil,
					},
				},
			}
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"info":      rawCurrency,
		"id":        id,
		"code":      code,
		"name":      this.SafeString(rawCurrency, "name"),
		"active":    active,
		"deposit":   deposit,
		"withdraw":  withdrawal,
		"networks":  networks,
		"fee":       withdrawFee,
		"precision": nil,
		"type": func() string {
			if isFiat {
				return "fiat"
			}
			return "crypto"
		}(),
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": minWithdraw,
				"max": nil,
			},
		},
	})
}

