/**
 * @method
 * @name bitvavo#fetchTrades
 * @see https://docs.bitvavo.com/docs/rest-api/get-trades/
 * @description get the list of most recent trades for a particular symbol
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] the latest time in ms to fetch entries for
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Bitvavo) FetchTradesAsync(symbol any, optionalArgs ...any) <-chan AsyncResult[[]Trade] {
	ch := make(chan AsyncResult[[]Trade], 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitvavo) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchTrades", "paginate", false)
	if paginate {

		r1 := <-this.FetchPaginatedCallDynamicAsync("fetchTrades", symbol, since, limit, paramsPaginate)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes82919 []any = r1.Value
		if retRes82919 == nil {
			ch <- AsyncResult[[]Trade]{Value: nil}
		} else {
			ch <- AsyncResult[[]Trade]{Value: TradesFromList(retRes82919)}
		}
		return nil
	}
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	if limit != nil {
		request["limit"] = mathMin(limit, 1000)
	}
	if since != nil {
		request["start"] = since
	}
	requestUntil, paramsUntil := this.HandleUntilOption("end", request, paramsPaginate)

	listEp1004 := <-this.PublicGetMarketTrades(this.Extend(requestUntil, paramsUntil))
	if listEp1004.Err != nil {
		panic(listEp1004.Err)
	}
	var response []any = listEp1004.Value

	//
	//     [
	//         {
	//             "id":"94154c98-6e8b-4e33-92a8-74e33fc05650",
	//             "timestamp":1590382761859,
	//             "amount":"0.06026079",
	//             "price":"8095.3",
	//             "side":"buy"
	//         }
	//     ]
	//
	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(response, market, since, limit))}
	return nil
}
func (this *Bitvavo) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades (public)
	//
	//     {
	//         "id":"94154c98-6e8b-4e33-92a8-74e33fc05650",
	//         "timestamp":1590382761859,
	//         "amount":"0.06026079",
	//         "price":"8095.3",
	//         "side":"buy"
	//     }
	//
	// createOrder, fetchOpenOrders, fetchOrders, editOrder (private)
	//
	//     {
	//         "id":"b0c86aa5-6ed3-4a2d-ba3a-be9a964220f4",
	//         "timestamp":1590505649245,
	//         "amount":"0.249825",
	//         "price":"183.49",
	//         "taker":true,
	//         "fee":"0.12038925",
	//         "feeCurrency":"EUR",
	//         "settled":true
	//     }
	//
	// fetchMyTrades (private)
	//
	//     {
	//         "id":"b0c86aa5-6ed3-4a2d-ba3a-be9a964220f4",
	//         "orderId":"af76d6ce-9f7c-4006-b715-bb5d430652d0",
	//         "timestamp":1590505649245,
	//         "market":"ETH-EUR",
	//         "side":"sell",
	//         "amount":"0.249825",
	//         "price":"183.49",
	//         "taker":true,
	//         "fee":"0.12038925",
	//         "feeCurrency":"EUR",
	//         "settled":true
	//     }
	//
	// watchMyTrades (private)
	//
	//     {
	//         "event": "fill",
	//         "timestamp": 1590964470132,
	//         "market": "ETH-EUR",
	//         "orderId": "85d082e1-eda4-4209-9580-248281a29a9a",
	//         "fillId": "861d2da5-aa93-475c-8d9a-dce431bd4211",
	//         "side": "sell",
	//         "amount": "0.1",
	//         "price": "211.46",
	//         "taker": true,
	//         "fee": "0.056",
	//         "feeCurrency": "EUR"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var priceString *string = this.SafeString(trade, "price")
	var amountString *string = this.SafeString(trade, "amount")
	var timestamp *int64 = this.SafeInteger(trade, "timestamp")
	var side *string = this.SafeString(trade, "side")
	var id *string = this.SafeString2(trade, "id", "fillId")
	var marketId *string = this.SafeString(trade, "market")
	var symbol *string = this.SafeSymbol(marketId, market, "-")
	var taker *bool = this.SafeBool(trade, "taker")
	var takerOrMaker *string = nil
	if taker != nil {
		takerOrMaker = SafeStringPtr(func() string {
			if taker != nil && *taker {
				return "taker"
			}
			return "maker"
		}())
	}
	var feeCostString *string = this.SafeString(trade, "fee")
	var fee map[string]any = nil
	if feeCostString != nil {
		var feeCurrencyId *string = this.SafeString(trade, "feeCurrency")
		var feeCurrencyCode *string = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrencyCode,
		}
	}
	var orderId *string = this.SafeString(trade, "orderId")
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"symbol":       symbol,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee":          fee,
	}, market)
}

