func (this *Bitvavo) ParseOHLCV(ohlcv any, optionalArgs ...any) OHLCV {
	//
	//     [
	//         1590383700000,
	//         "8088.5",
	//         "8088.5",
	//         "8088.5",
	//         "8088.5",
	//         "0.04788623"
	//     ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return OHLCVFromList([]any{this.SafeInteger(ohlcv, 0), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 4), this.SafeNumber(ohlcv, 5)})
}
func (this *Bitvavo) FetchOHLCVRequest(symbol any, optionalArgs ...any) map[string]any {
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market":   market["id"],
		"interval": this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	if since != nil {
		// https://github.com/ccxt/ccxt/issues/9227
		var duration int64 = this.ParseTimeframe(timeframe)
		request["start"] = since
		var sinceLimit int64 = func() int64 {
			if limit == nil {
				return 1440
			}
			return min(*limit, 1440)
		}()
		request["end"] = this.Sum(since, ((sinceLimit * duration) * 1000))
	}
	if limit != nil {
		request["limit"] = mathMin(limit, 1440) // default 1440, max 1440
	} else if since != nil {
		request["limit"] = 1440
	}
	requestUntil, paramsUntil := this.HandleUntilOption("end", request, params)
	return this.Extend(requestUntil, paramsUntil)
}

/**
 * @method
 * @name bitvavo#fetchOHLCV
 * @see https://docs.bitvavo.com/docs/rest-api/get-candlestick-data/
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] the latest time in ms to fetch entries for
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Bitvavo) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitvavo) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchOHLCV", "paginate", false)
	if paginate {

		r1 := <-this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, paramsPaginate, 1440)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes116119 []any = r1.Value
		if retRes116119 == nil {
			ch <- AsyncResult[[]OHLCV]{Value: nil}
		} else {
			ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(retRes116119)}
		}
		return nil
	}
	var request map[string]any = this.FetchOHLCVRequest(symbol, timeframe, since, limit, paramsPaginate)

	listEp1400 := <-this.PublicGetMarketCandles(request)
	if listEp1400.Err != nil {
		panic(listEp1400.Err)
	}
	var response []any = listEp1400.Value

	//
	//     [
	//         [1590383700000,"8088.5","8088.5","8088.5","8088.5","0.04788623"],
	//         [1590383580000,"8091.3","8091.5","8091.3","8091.5","0.04931221"],
	//         [1590383520000,"8090.3","8092.7","8090.3","8092.5","0.04001286"],
	//     ]
	//
	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(this.ToArray(response), market, timeframe, since, limit))}
	return nil
}
func (this *Bitvavo) ParseBalanceList(response any) map[string]any {
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": nil,
		"datetime":  nil,
	}
	for i := 0; i < GetArrayLength(response); i++ {
		var balance map[string]any = SafeMapTyped(response, i)
		var currencyId *string = this.SafeString(balance, "symbol")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(balance, "available")
		account["used"] = this.SafeString(balance, "inOrder")
		if code != nil {
			result[*code] = account
		}
	}
	return this.SafeBalance(result).(map[string]any)
}

