func (this *Bitvavo) CreateOrderRequest(symbol string, typeVar string, side string, amount any, optionalArgs ...any) map[string]any {
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if false {
		panic(ArgumentsRequired(this.Id + " requires a type argument"))
	}
	if false {
		panic(ArgumentsRequired(this.Id + " requires a side argument"))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market":    market["id"],
		"side":      side,
		"orderType": typeVar,
	}
	var isMarketOrder bool = (typeVar == "market") || (typeVar == "stopLoss") || (typeVar == "takeProfit")
	var isLimitOrder bool = (typeVar == "limit") || (typeVar == "stopLossLimit") || (typeVar == "takeProfitLimit")
	var timeInForce *string = this.SafeString(params, "timeInForce")
	var triggerPrice *string = this.SafeStringN(params, []any{"triggerPrice", "stopPrice", "triggerAmount"})
	var postOnly bool = this.IsPostOnly(isMarketOrder, false, params)
	var stopLossPrice *string = this.SafeString(params, "stopLossPrice")     // trigger when price crosses from above to below this value
	var takeProfitPrice *string = this.SafeString(params, "takeProfitPrice") // trigger when price crosses from below to above this value
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"timeInForce", "triggerPrice", "stopPrice", "stopLossPrice", "takeProfitPrice"})
	var paramsCost any = paramsOmitted
	if isMarketOrder {
		paramsCost = this.Omit(paramsOmitted, []any{"cost"})
	}
	if isMarketOrder {
		var cost *float64 = nil
		if price != nil {
			var priceString *string = this.NumberToString(price)
			var amountString *string = this.NumberToString(amount)
			var quoteAmount *string = Precise.StringMul(amountString, priceString)
			cost = this.ParseNumber(quoteAmount)
		} else {
			cost = this.SafeNumber(paramsOmitted, "cost")
		}
		if cost != nil {
			var precision *float64 = this.SafeNumber(this.Currency(market["quote"]), "precision")
			request["amountQuote"] = this.DecimalToPrecision(cost, TRUNCATE, precision, this.PrecisionMode)
		} else {
			request["amount"] = this.AmountToPrecision(symbol, amount)
		}
	} else if isLimitOrder {
		request["price"] = this.PriceToPrecision(symbol, price)
		request["amount"] = this.AmountToPrecision(symbol, amount)
	}
	var isTakeProfit bool = (takeProfitPrice != nil) || (typeVar == "takeProfit") || (typeVar == "takeProfitLimit")
	var isStopLoss bool = (stopLossPrice != nil) || (triggerPrice != nil) && (!isTakeProfit) || (typeVar == "stopLoss") || (typeVar == "stopLossLimit")
	if isStopLoss {
		if stopLossPrice != nil {
			triggerPrice = stopLossPrice
		}
		request["orderType"] = func() string {
			if isMarketOrder {
				return "stopLoss"
			}
			return "stopLossLimit"
		}()
	} else if isTakeProfit {
		if takeProfitPrice != nil {
			triggerPrice = takeProfitPrice
		}
		request["orderType"] = func() string {
			if isMarketOrder {
				return "takeProfit"
			}
			return "takeProfitLimit"
		}()
	}
	if triggerPrice != nil {
		request["triggerAmount"] = this.PriceToPrecision(symbol, triggerPrice)
		request["triggerType"] = "price"
		request["triggerReference"] = "lastTrade" // 'bestBid', 'bestAsk', 'midPrice'
	}
	if (timeInForce != nil) && (timeInForce == nil || *timeInForce != "PO") {
		request["timeInForce"] = timeInForce
	}
	if postOnly {
		request["postOnly"] = true
	}
	var operatorIdparamsOperatorIdVariable []any = this.HandleOptionAndParams(paramsCost, "createOrder", "operatorId")
	operatorId := GetValue(operatorIdparamsOperatorIdVariable, 0)
	paramsOperatorId := operatorIdparamsOperatorIdVariable[1]
	if operatorId != nil {
		request["operatorId"] = this.ParseToInt(operatorId)
	} else {
		panic(ArgumentsRequired(this.Id + " createOrder() requires an operatorId in params or options, eg: exchange.options['operatorId'] = 1234567890"))
	}
	selfTradePrevention, paramsSelfTradePrevention := this.HandleOptionStringAndParams(paramsOperatorId, "createOrder", "selfTradePrevention")
	if selfTradePrevention != nil {
		if selfTradePrevention != nil && *selfTradePrevention == "EXPIRE_BOTH" {
			request["selfTradePrevention"] = "cancelBoth"
		} else {
			request["selfTradePrevention"] = selfTradePrevention
		}
	}
	return this.Extend(request, paramsSelfTradePrevention)
}

