func (this *Bitvavo) cancelAllOrdersAfterBody(ch chan AsyncResult[map[string]any], timeout int64, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if timeout > 300000 {
		panic(BadRequest(this.Id + " cancelAllOrdersAfter() timeout should be less than or equal to 300000 milliseconds"))
	}
	if (timeout > 0) && (timeout < 10000) {
		panic(BadRequest(this.Id + " cancelAllOrdersAfter() timeout should be 0 or greater than or equal to 10000 milliseconds"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	codGroupId, paramsCodGroupId := this.HandleOptionIntegerAndParams(params, "cancelAllOrdersAfter", "codGroupId", 1)
	var request map[string]any = map[string]any{
		"codGroupId": codGroupId,
		"expiryAfterSeconds": func() any {
			if timeout > 0 {
				return this.ParseToInt(float64(timeout) / 1000)
			}
			return 0
		}(),
	}

	r1 := <-this.PrivatePostCancelOrdersAfter(this.Extend(request, paramsCodGroupId))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Value

	//
	//     {
	//         "codGroupId": 1,
	//         "timeOfExpirySeconds": 17202139111
	//     }
	//
	ch <- AsyncResult[map[string]any]{Value: response}
	return nil
}

