func (this *Bitvavo) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// cancelOrder, cancelAllOrders
	//
	//     {
	//         "orderId": "2e7ce7fc-44e2-4d80-a4a7-d079c4750b61"
	//     }
	//
	// createOrder, fetchOrder, fetchOpenOrders, fetchOrders, editOrder
	//
	//     {
	//         "orderId":"af76d6ce-9f7c-4006-b715-bb5d430652d0",
	//         "market":"ETH-EUR",
	//         "created":1590505649241,
	//         "updated":1590505649241,
	//         "status":"filled",
	//         "side":"sell",
	//         "orderType":"market",
	//         "amount":"0.249825",
	//         "amountRemaining":"0",
	//         "price": "183.49", // limit orders only
	//         "onHold":"0",
	//         "onHoldCurrency":"ETH",
	//         "filledAmount":"0.249825",
	//         "filledAmountQuote":"45.84038925",
	//         "feePaid":"0.12038925",
	//         "feeCurrency":"EUR",
	//         "fills":[
	//             {
	//                 "id":"b0c86aa5-6ed3-4a2d-ba3a-be9a964220f4",
	//                 "timestamp":1590505649245,
	//                 "amount":"0.249825",
	//                 "price":"183.49",
	//                 "taker":true,
	//                 "fee":"0.12038925",
	//                 "feeCurrency":"EUR",
	//                 "settled":true
	//             }
	//         ],
	//         "selfTradePrevention":"decrementAndCancel",
	//         "visible":false,
	//         "disableMarketProtection":false
	//         "timeInForce": "GTC",
	//         "postOnly": true,
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "orderId")
	var timestamp *int64 = this.SafeInteger(order, "created")
	var marketId *string = this.SafeString(order, "market")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, "-")
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var side *string = this.SafeString(order, "side")
	var typeVar *string = this.SafeString(order, "orderType")
	var price *string = this.SafeString(order, "price")
	var amount *string = this.SafeString(order, "amount")
	var remaining *string = this.SafeString(order, "amountRemaining")
	var filled *string = this.SafeString(order, "filledAmount")
	var cost *string = this.SafeString(order, "filledAmountQuote")
	if cost == nil {
		var amountQuote *string = this.SafeString(order, "amountQuote")
		var amountQuoteRemaining *string = this.SafeString(order, "amountQuoteRemaining")
		cost = Precise.StringSub(amountQuote, amountQuoteRemaining)
	}
	var fee map[string]any = nil
	var feeCost *float64 = this.SafeNumber(order, "feePaid")
	if feeCost != nil {
		var feeCurrencyId *string = this.SafeString(order, "feeCurrency")
		var feeCurrencyCode *string = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrencyCode,
		}
	}
	var rawTrades []any = SafeListTypedDefault(order, "fills", []any{})
	var timeInForce *string = this.SafeString(order, "timeInForce")
	var postOnly *bool = this.SafeBool(order, "postOnly")
	// https://github.com/ccxt/ccxt/issues/8489
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        timeInForce,
		"postOnly":           postOnly,
		"side":               side,
		"price":              price,
		"triggerPrice":       this.SafeNumber(order, "triggerPrice"),
		"amount":             amount,
		"cost":               cost,
		"average":            nil,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             rawTrades,
	}, marketResolved)
}
