func (this *Bitvavo) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"awaiting_processing":         "pending",
		"awaiting_email_confirmation": "pending",
		"awaiting_bitvavo_inspection": "pending",
		"approved":                    "pending",
		"sending":                     "pending",
		"in_mempool":                  "pending",
		"processed":                   "pending",
		"completed":                   "ok",
		"canceled":                    "canceled",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitvavo) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// withdraw
	//
	//     {
	//         "success": true,
	//         "symbol": "BTC",
	//         "amount": "1.5"
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "timestamp": 1542967486256,
	//         "symbol": "BTC",
	//         "amount": "0.99994",
	//         "address": "BitcoinAddress",
	//         "paymentId": "10002653",
	//         "txId": "927b3ea50c5bb52c6854152d305dfa1e27fc01d10464cf10825d96d69d235eb3",
	//         "fee": "0.00006",
	//         "status": "awaiting_processing"
	//     }
	//
	// fetchDeposits
	//
	//     {
	//         "timestamp":1590492401000,
	//         "symbol":"ETH",
	//         "amount":"0.249825",
	//         "fee":"0",
	//         "status":"completed",
	//         "txId":"0x5167b473fd37811f9ef22364c3d54726a859ef9d98934b3a1e11d7baa8d2c2e2"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id any = nil
	var timestamp *int64 = this.SafeInteger(transaction, "timestamp")
	var currencyId *string = this.SafeString(transaction, "symbol")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var status *string = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	var amount *float64 = this.SafeNumber(transaction, "amount")
	var address *string = this.SafeString(transaction, "address")
	var txid *string = this.SafeString(transaction, "txId")
	var fee map[string]any = nil
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	if feeCost != nil {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": code,
		}
	}
	var typeVar string
	if (InOp(transaction, "success")) || (InOp(transaction, "address")) {
		typeVar = "withdrawal"
	} else {
		typeVar = "deposit"
	}
	var tag *string = this.SafeString(transaction, "paymentId")
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"addressFrom": nil,
		"address":     address,
		"addressTo":   address,
		"tagFrom":     nil,
		"tag":         tag,
		"tagTo":       tag,
		"type":        typeVar,
		"amount":      amount,
		"currency":    code,
		"status":      status,
		"updated":     nil,
		"fee":         fee,
		"network":     nil,
		"comment":     nil,
		"internal":    nil,
	})
}
func (this *Bitvavo) ParseDepositWithdrawFee(fee any, optionalArgs ...any) map[string]any {
	//
	//   {
	//       "symbol": "1INCH",
	//       "name": "1inch",
	//       "decimals": 8,
	//       "depositFee": "0",
	//       "depositConfirmations": 64,
	//       "depositStatus": "OK",
	//       "withdrawalFee": "6.1",
	//       "withdrawalMinAmount": "6.1",
	//       "withdrawalStatus": "OK",
	//       "networks": [
	//         "ETH"
	//       ],
	//       "message": ""
	//   }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var result map[string]any = map[string]any{
		"info": fee,
		"withdraw": map[string]any{
			"fee":        this.SafeNumber(fee, "withdrawalFee"),
			"percentage": false,
		},
		"deposit": map[string]any{
			"fee":        this.SafeNumber(fee, "depositFee"),
			"percentage": false,
		},
		"networks": map[string]any{},
	}
	var networks []any = SafeListTyped(fee, "networks")
	var networkId *string = this.SafeString(networks, 0) // Bitvavo currently only supports one network per currency
	var currencyCode *string = this.SafeString(currency, "code")
	if networkId != nil && *networkId == "Mainnet" {
		networkId = currencyCode
	}
	var networkCode *string = this.NetworkIdToCode(networkId, currencyCode)
	if networkCode != nil {
		AddElementToObject(result["networks"], networkCode, map[string]any{
			"deposit":  result["deposit"],
			"withdraw": result["withdraw"],
		})
	}
	return result
}

